@namespace sv_5bbeb6b4dccb45f8bdbfad31eafacc3d.Components.Pages.Settings
@using sv_5bbeb6b4dccb45f8bdbfad31eafacc3d.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h3 class="mb-4">Appearance Settings</h3>

    @if (_loading)
    {
        <div class="text-center py-5">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(_message))
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @_message
                <button type="button" class="btn-close" @onclick="() => _message = null"></button>
            </div>
        }

        <div class="row">
            <div class="col-md-7">
                <div class="card mb-3">
                    <div class="card-body">
                        <h5 class="card-title mb-3">Theme</h5>
                        @foreach (var theme in _themes)
                        {
                            <div class="form-check mb-2">
                                <input class="form-check-input" type="radio" name="theme"
                                       id="@($"theme-{theme}")" value="@theme"
                                       checked="@(_theme == theme)"
                                       @onchange="() => _theme = theme" />
                                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                            </div>
                        }
                    </div>
                </div>

                <div class="card mb-3">
                    <div class="card-body">
                        <h5 class="card-title mb-3">Font Size</h5>
                        @foreach (var size in _fontSizes)
                        {
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="@($"fs-{size}")" value="@size"
                                       checked="@(_fontSize == size)"
                                       @onchange="() => _fontSize = size" />
                                <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                            </div>
                        }
                    </div>
                </div>

                <div class="card mb-3">
                    <div class="card-body">
                        <h5 class="card-title mb-3">Language</h5>
                        <select class="form-select" @bind="_language">
                            @foreach (var lang in _languages)
                            {
                                <option value="@lang">@lang</option>
                            }
                        </select>
                    </div>
                </div>

                <div class="card mb-3">
                    <div class="card-body">
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" role="switch" id="compactMode"
                                   @bind="_compactMode" />
                            <label class="form-check-label" for="compactMode">
                                Compact Mode
                                <small class="d-block text-muted">Reduce spacing and padding throughout the UI</small>
                            </label>
                        </div>
                    </div>
                </div>
            </div>

            <div class="col-md-5">
                <div class="card sticky-top" style="top:1rem;">
                    <div class="card-header">
                        <h5 class="mb-0">Live Preview</h5>
                    </div>
                    <div class="card-body @PreviewBackgroundClass()" style="@PreviewStyle()">
                        <div class="@PreviewPaddingClass()">
                            <h6 style="@PreviewFontStyle()">Sample Heading</h6>
                            <p class="mb-2" style="@PreviewFontStyle()">
                                This is how your content will look with the selected settings.
                            </p>
                            <div class="d-flex gap-2 mb-2">
                                <span class="badge bg-primary">Tag 1</span>
                                <span class="badge bg-secondary">Tag 2</span>
                            </div>
                            <button class="btn btn-sm btn-primary" style="@PreviewFontStyle()">
                                Sample Button
                            </button>
                        </div>
                        <div class="mt-2 small text-muted">
                            Theme: @_theme · Font: @_fontSize · Lang: @_language · Compact: @(_compactMode ? "On" : "Off")
                        </div>
                    </div>
                </div>
            </div>
        </div>

        <button class="btn btn-primary mt-3" @onclick="SaveAsync" disabled="@_saving">
            @if (_saving)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            }
            Save
        </button>
    }
</div>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _message;

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _message = null;
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _message = "Appearance settings saved!";
        _saving = false;
    }

    private string PreviewBackgroundClass() => _theme switch
    {
        "Dark" => "text-light",
        _ => ""
    };

    private string PreviewStyle()
    {
        var bg = _theme switch
        {
            "Dark" => "background-color:#1e1e1e;color:#e0e0e0;",
            "Light" => "background-color:#ffffff;color:#212529;",
            _ => "background-color:#f8f9fa;color:#212529;"
        };
        return bg + "transition:all 0.3s ease;border-radius:0.375rem;";
    }

    private string PreviewFontStyle() => _fontSize switch
    {
        "Small" => "font-size:0.85rem;",
        "Large" => "font-size:1.15rem;",
        _ => "font-size:1rem;"
    };

    private string PreviewPaddingClass() => _compactMode ? "p-1" : "p-2";
}

.settings-dashboard {
    display: flex;
    gap: 1.5rem;
    min-height: 70vh;
}

::deep .settings-sidebar {
    min-width: 200px;
    max-width: 220px;
    border-right: 1px solid #dee2e6;
    padding-right: 0.5rem;
}

::deep .settings-sidebar .nav-link {
    color: #495057;
    border-radius: 0.375rem;
    padding: 0.6rem 1rem;
    margin-bottom: 0.25rem;
    border: none;
    background: none;
    font-size: 0.95rem;
}

::deep .settings-sidebar .nav-link:hover {
    background-color: #f0f0f0;
    color: #212529;
}

::deep .settings-sidebar .nav-link.active {
    background-color: #0d6efd;
    color: #fff;
    font-weight: 500;
}

.settings-content {
    flex: 1;
    min-width: 0;
}

::deep .settings-section {
    max-width: 800px;
}

@media (max-width: 768px) {
    .settings-dashboard {
        flex-direction: column;
    }

    ::deep .settings-sidebar {
        min-width: 100%;
        max-width: 100%;
        border-right: none;
        border-bottom: 1px solid #dee2e6;
        padding-right: 0;
        padding-bottom: 0.5rem;
    }

    ::deep .settings-sidebar .nav {
        flex-direction: row !important;
        flex-wrap: wrap;
        gap: 0.25rem;
    }

    ::deep .settings-sidebar .nav-link {
        padding: 0.4rem 0.75rem;
        font-size: 0.875rem;
    }
}

